export function rearPanelPlacement(camera,center,settings){const dx=camera[0]-center[0],dz=camera[2]-center[2],length=Math.hypot(dx,dz)||1,ux=Math.hypot(dx,dz)<.000001?0:dx/length,uz=Math.hypot(dx,dz)<.000001?1:dz/length,depth=8+Math.abs(settings.panelZ),side=settings.panelX;return {position:[center[0]-ux*depth+uz*side,center[1]+settings.panelY,center[2]-uz*depth-ux*side],front:[ux,0,uz]}}
